<script setup lang="ts">
import type { BsJournalDetailCopy, BsJournalDetailForm, BsJournalDetailView } from '../types/journalDetailPresentation'
defineProps<{ copy: BsJournalDetailCopy; view: BsJournalDetailView }>()
const form = defineModel<BsJournalDetailForm>('form', { required: true })
const emit = defineEmits<{ close: []; retry: []; retryTags: []; assignTag: []; removeTag: [id: string]; upload: [event: Event]; download: [id: string]; delete: [id: string]; navigate: [id: string]; reverse: [] }>()
function field<K extends keyof BsJournalDetailForm>(key: K, value: BsJournalDetailForm[K]) { form.value = { ...form.value, [key]: value } }
</script>
<template>
  <BsDialog :visible="view.visible" :title="view.title" :show-header="false" size="md" :dirty="view.dirty" :pending="view.pending" @update:visible="value => { if (!value) emit('close') }">
    <template #default="{ close }"><BsStack gap="none" overflow="hidden">
      <BsInline as="header" gap="md" align="start" justify="between"><BsBox><BsHeading :level="2" size="body">{{ view.title }}</BsHeading><BsText size="sm" tone="muted"><BsStatusBadge v-if="view.status" :status="view.status"/><BsText v-if="view.type" as="span">{{ view.type }}</BsText><BsText v-if="view.reference" as="span" emphasis="semibold">{{ view.reference }}</BsText></BsText></BsBox><BsButton :aria-label="copy.close" size="sm" @click="close"><BsIcon name="close"/></BsButton></BsInline>
      <BsStateSurface v-if="view.loadError" state="error" :title="copy.failed" :action-label="copy.retry" @action="emit('retry')"/><BsSectionSkeleton v-else-if="view.loading" variant="table" :aria-label="copy.loading"/>
      <BsStack v-else gap="lg" grow>
        <BsDescriptionList :columns="2"><BsDescriptionItem v-for="item in view.descriptions" :key="item.id" :term="item.label">{{ item.value }}</BsDescriptionItem><BsDescriptionItem v-if="view.source" :term="view.source.label"><BsLink :to="view.source.to">{{ copy.openSource }}</BsLink></BsDescriptionItem></BsDescriptionList>
        <BsBox as="section"><BsHeading :level="3" size="body">{{ copy.journal }}</BsHeading><BsDataTable :value="view.entries" data-key="id" :label="copy.journal" :columns="[{ key: 'account', header: copy.account }, { key: 'debit', field: 'debit', header: copy.debit, align: 'end' }, { key: 'credit', field: 'credit', header: copy.credit, align: 'end' }]"><template #cell-account="{ row }"><BsText as="span">{{ row.account }}</BsText><BsText v-if="row.memo" as="span" size="xs" tone="muted">{{ row.memo }}</BsText></template></BsDataTable><BsInline gap="md" wrap justify="between" padding="md" surface="muted" radius="control"><BsText as="span">{{ copy.totals }}</BsText><BsText as="span">{{ copy.debit }}: <BsText as="span" dir="ltr">{{ view.debit }}</BsText> · {{ copy.credit }}: <BsText as="span" dir="ltr">{{ view.credit }}</BsText></BsText></BsInline></BsBox>
        <BsStack v-if="view.tags.visible" gap="sm"><BsHeading :level="3" size="body">{{ copy.tags }}</BsHeading><BsText size="sm" tone="muted">{{ copy.tagsHint }}</BsText><BsSectionSkeleton v-if="view.tags.loading" variant="cards"/><BsText v-else-if="view.tags.failed" role="alert" tone="danger">{{ copy.tagError }} <BsButton variant="link" @click="emit('retryTags')">{{ copy.retry }}</BsButton></BsText><template v-else><BsList v-if="view.tags.assigned.length" marker="none"><BsListItem v-for="tag in view.tags.assigned" :key="tag.id"><BsText>{{ tag.name }}</BsText><BsButton v-if="view.tags.canManage" :disabled="view.tags.pending" :aria-label="copy.removeTag + ' ' + tag.name" size="sm" @click="emit('removeTag', tag.id)"><BsIcon name="close" :size="14"/></BsButton></BsListItem></BsList><BsText v-else size="sm" tone="muted">{{ copy.noTags }}</BsText><BsInline v-if="view.tags.canManage && view.tags.choices.length" gap="sm" wrap align="end"><BsFloatingField :label="copy.chooseTag"><BsSelect :model-value="form.selectedTag" :label="copy.chooseTag" :disabled="view.tags.pending" :options="[{ value: '', label: copy.chooseTag }, ...view.tags.choices]" option-label="label" option-value="value" native @update:model-value="field('selectedTag', String($event))"/></BsFloatingField><BsButton :disabled="!form.selectedTag || view.tags.pending" @click="emit('assignTag')">{{ copy.assignTag }}</BsButton></BsInline><BsText v-if="view.tags.noOptions" size="sm" tone="muted">{{ copy.noTagOptions }}</BsText><BsText v-if="view.tags.error" role="alert" tone="danger">{{ view.tags.error }}</BsText></template></BsStack>
        <BsBox as="section"><BsInline justify="between"><BsHeading :level="3" size="body">{{ copy.attachments }}</BsHeading><BsFieldLabel v-if="view.canUpload">{{ view.uploading ? copy.saving : copy.upload }}<BsFileInput accept="application/pdf,image/png,image/jpeg,image/webp" :disabled="view.uploading" bare hide-control @change="emit('upload', $event)"/></BsFieldLabel></BsInline><BsUsageMeter v-if="view.canUpload && view.storage" compact :item="view.storage"/><BsStack v-if="view.attachments.length" gap="sm"><BsInline v-for="item in view.attachments" :key="item.id" justify="between" surface="muted" radius="control"><BsButton variant="link" @click="emit('download', item.id)">{{ item.name }}</BsButton><BsButton v-if="view.canDelete" :aria-label="copy.delete" size="sm" @click="emit('delete', item.id)"><BsIcon name="delete" :size="18"/></BsButton></BsInline></BsStack><BsText v-else size="sm" tone="muted">{{ copy.noAttachments }}</BsText></BsBox>
        <BsBox v-if="view.relationships.length" as="section"><BsHeading :level="3" size="body">{{ copy.relationships }}</BsHeading><BsText v-for="relationship in view.relationships" :key="relationship.id">{{ relationship.label }} <BsButton variant="link" @click="emit('navigate', relationship.id)">{{ relationship.reference }}</BsButton></BsText></BsBox><BsText v-if="view.restriction" size="sm" tone="muted">{{ view.restriction }}</BsText>
        <BsCard v-if="form.confirming" variant="flat" padding="md"><BsStack gap="md"><BsText size="sm">{{ copy.reverseExplanation }}</BsText><BsFloatingField :label="copy.reverseReason"><BsInput :model-value="form.reason" :placeholder="copy.reasonPlaceholder" @update:model-value="field('reason', String($event ?? ''))"/></BsFloatingField><BsInline gap="sm" justify="end"><BsButton @click="field('confirming', false)">{{ copy.cancel }}</BsButton><BsButton :disabled="view.reversing" variant="danger" @click="emit('reverse')">{{ view.reversing ? copy.reversing : copy.reverseConfirm }}</BsButton></BsInline></BsStack></BsCard><BsText v-if="view.error" role="alert" tone="danger">{{ view.error }}</BsText>
      </BsStack><BsBox v-if="view.canReverse && !form.confirming" as="footer"><BsButton @click="field('confirming', true)">{{ copy.reverseAction }}</BsButton></BsBox>
    </BsStack></template>
  </BsDialog>
</template>
